  `next_seq` INT NOT NULL DEFAULT 1,
  PRIMARY KEY (`scope`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promotion_moves` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `run_id` BIGINT,
  `student_id` BIGINT NOT NULL,
  `enrollment_id` BIGINT,
  `session_id` BIGINT,
  `from_class_level_id` BIGINT,
  `to_class_level_id` BIGINT,
  `decision` TEXT NOT NULL,
  `basis` TEXT NOT NULL DEFAULT 'manual',
  `reason` TEXT,
  `moved_on` DATE NOT NULL DEFAULT (CURDATE()),
  `moved_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `recommended_by` TEXT,
  `ptm_interaction_id` BIGINT,
  PRIMARY KEY (`id`),
  KEY `idx_moves_run` (`run_id`),
  KEY `idx_moves_student` (`student_id`, `moved_on`),
  CONSTRAINT `promotion_moves_basis_check` CHECK ((basis IN ('result', 'manual', 'no_result'))),
  CONSTRAINT `promotion_moves_decision_check` CHECK ((decision IN ('promoted', 'retained', 'graduated')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promotion_runs` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `from_session_id` BIGINT,
  `to_session_id` BIGINT,
  `center_id` BIGINT,
  `promoted_count` INT NOT NULL DEFAULT 0,
  `retained_count` INT NOT NULL DEFAULT 0,
  `graduated_count` INT NOT NULL DEFAULT 0,
  `skipped_count` INT NOT NULL DEFAULT 0,
  `run_by` BIGINT,
  `run_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `notes` TEXT,
  `session_id` BIGINT,
  `kind` TEXT NOT NULL DEFAULT 'session',
  PRIMARY KEY (`id`),
  CONSTRAINT `promotion_runs_kind_check` CHECK ((kind IN ('session', 'manual')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ptm_interactions` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `meeting_id` BIGINT,
  `student_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT,
  `center_id` BIGINT NOT NULL,
  `mentor_id` BIGINT,
  `interaction_date` DATE NOT NULL DEFAULT (CURDATE()),
  `mode` TEXT NOT NULL DEFAULT 'in_person',
  `parent_present` TEXT NOT NULL DEFAULT 'mother',
  `engagement` TEXT NOT NULL DEFAULT 'neutral',
  `attendance_pct` DECIMAL(5,2),
  `marks_pct` DECIMAL(5,2),
  `discussion` TEXT,
  `concerns` TEXT,
  `action_items` TEXT,
  `follow_up_required` TINYINT(1) NOT NULL DEFAULT 0,
  `follow_up_date` DATE,
  `follow_up_mode` TEXT,
  `follow_up_status` VARCHAR(255) NOT NULL DEFAULT 'pending',
  `follow_up_notes` TEXT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `follow_up_assignee_id` BIGINT,
  `concern_tags` JSON NOT NULL DEFAULT '[]',
  `commitment_tags` JSON NOT NULL DEFAULT '[]',
  `follow_up_priority` TEXT,
  `follow_up_owner` TEXT,
  `confidence` SMALLINT,
  `support_needed` TEXT,
  `centre_feedback` TEXT,
  `follow_up_description` TEXT,
  PRIMARY KEY (`id`),
  KEY `idx_ptmi_assignee` (`follow_up_assignee_id`, `follow_up_status`),
  KEY `idx_ptmi_center_date` (`center_id`, `interaction_date`),
  KEY `idx_ptmi_followup` (`follow_up_status`, `follow_up_date`),
  KEY `idx_ptmi_student` (`student_id`),
  CONSTRAINT `ptm_confidence_check` CHECK (((confidence IS NULL) OR ((confidence >= 1) AND (confidence <= 5)))),
  CONSTRAINT `ptm_follow_up_priority_check` CHECK (((follow_up_priority IS NULL) OR (follow_up_priority IN ('high', 'medium', 'low')))),
  CONSTRAINT `ptm_interactions_engagement_check` CHECK ((engagement IN ('attentive', 'neutral', 'resistant'))),
  CONSTRAINT `ptm_interactions_follow_up_mode_check` CHECK ((follow_up_mode IN ('phone', 'home_visit', 'center_visit', 'video'))),
  CONSTRAINT `ptm_interactions_follow_up_status_check` CHECK ((follow_up_status IN ('pending', 'done', 'cancelled'))),
  CONSTRAINT `ptm_interactions_mode_check` CHECK ((mode IN ('in_person', 'phone', 'video', 'home_visit'))),
  CONSTRAINT `ptm_interactions_parent_present_check` CHECK ((parent_present IN ('mother', 'father', 'both', 'guardian', 'none')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ptm_meetings` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `title` TEXT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT,
  `meeting_date` DATE NOT NULL,
  `start_time` TIME,
  `end_time` TIME,
  `mode` TEXT NOT NULL DEFAULT 'in_person',
  `status` TEXT NOT NULL DEFAULT 'scheduled',
  `agenda` TEXT,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_ptm_meet` (`center_id`, `meeting_date`),
  CONSTRAINT `ptm_meetings_mode_check` CHECK ((mode IN ('in_person', 'phone', 'video', 'home_visit'))),
  CONSTRAINT `ptm_meetings_status_check` CHECK ((status IN ('scheduled', 'ongoing', 'completed', 'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `role_menu_overrides` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `role` VARCHAR(255) NOT NULL,
  `menu_key` VARCHAR(255) NOT NULL,
  `hidden` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `role_menu_overrides_role_menu_key_key` (`role`, `menu_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `schema_migrations` (
  `filename` VARCHAR(255) NOT NULL,
  `applied_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`filename`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sport_attendance` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `sport_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `att_date` DATE NOT NULL,
  `status` TEXT NOT NULL,
  `marked_by` BIGINT,
  `marked_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `sport_attendance_sport_id_student_id_att_date_key` (`sport_id`, `student_id`, `att_date`),
  KEY `idx_sport_att_day` (`sport_id`, `att_date`),
  CONSTRAINT `sport_attendance_status_check` CHECK ((status IN ('present', 'absent')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sport_marks` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `test_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `marks` DECIMAL(6,2),
  `is_absent` TINYINT(1) NOT NULL DEFAULT 0,
  `remarks` TEXT,
  `marked_by` BIGINT,
  `marked_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `sport_marks_test_id_student_id_key` (`test_id`, `student_id`),
  CONSTRAINT `sport_marks_absent` CHECK ((NOT (is_absent AND (marks IS NOT NULL)))),
  CONSTRAINT `sport_marks_marks_check` CHECK (((marks IS NULL) OR (marks >= (0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sport_students` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `sport_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `joined_on` DATE NOT NULL DEFAULT (CURDATE()),
  `left_on` DATE,
  `added_by` BIGINT,
  `is_special` TINYINT(1) NOT NULL DEFAULT 0,
  `speciality` TEXT,
  `special_level` TEXT,
  `special_marked_by` BIGINT,
  `special_marked_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `remarks` TEXT,
  `remarks_updated_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `remarks_by` BIGINT,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sport_students_sport_id_student_id_key` (`sport_id`, `student_id`),
  KEY `idx_sport_students_special` (`sport_id`),
  KEY `idx_sport_students_student` (`student_id`),
  CONSTRAINT `sport_students_special_level_check` CHECK (((special_level IS NULL) OR (special_level IN ('centre', 'district', 'state', 'national'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sport_tests` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `sport_id` BIGINT NOT NULL,
  `title` TEXT NOT NULL,
  `test_date` DATE NOT NULL DEFAULT (CURDATE()),
  `max_marks` DECIMAL(6,2) NOT NULL,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_sport_tests_sport` (`sport_id`, `test_date`),
  CONSTRAINT `sport_tests_max_marks_check` CHECK ((max_marks > (0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sports` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `center_id` BIGINT NOT NULL,
  `name` TEXT NOT NULL,
  `description` TEXT,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sports_centre_name` (`center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sports_visits` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `visit_date` DATE NOT NULL,
  `check_in_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `check_in_lat` DOUBLE,
  `check_in_lng` DOUBLE,
  `check_in_distance_m` INT,
  `check_in_accuracy_m` INT,
  `check_out_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `check_out_lat` DOUBLE,
  `check_out_lng` DOUBLE,
  `check_out_distance_m` INT,
  `worked_minutes` INT,
  `sports_covered` JSON NOT NULL DEFAULT '[]',
  `children_count` INT,
  `activities` TEXT,
  `highlights` TEXT,
  `issues` TEXT,
  `report_submitted_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `closed_late` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `_u_uq_sports_visit_open` TINYINT AS (CASE WHEN (report_submitted_at IS NULL) THEN 1 END) VIRTUAL INVISIBLE,
  PRIMARY KEY (`id`),
  KEY `idx_sports_visits_centre` (`center_id`, `visit_date`),
  KEY `idx_sports_visits_day` (`visit_date`, `user_id`),
  UNIQUE KEY `uq_sports_visit_open` (`user_id`, `_u_uq_sports_visit_open`),
  CONSTRAINT `sports_visit_report` CHECK (((report_submitted_at IS NULL) OR (activities IS NOT NULL))),
  CONSTRAINT `sports_visits_children_count_check` CHECK (((children_count IS NULL) OR (children_count >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_attendance` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `att_date` DATE NOT NULL,
  `check_in_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `check_in_lat` DOUBLE,
  `check_in_lng` DOUBLE,
  `check_in_distance_m` INT,
  `check_in_accuracy_m` INT,
  `check_out_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `check_out_lat` DOUBLE,
  `check_out_lng` DOUBLE,
  `check_out_distance_m` INT,
  `worked_minutes` INT,
  `status` TEXT NOT NULL DEFAULT 'present',
  `within_geofence` TINYINT(1) NOT NULL DEFAULT 1,
  `override_by` BIGINT,
  `override_reason` TEXT,
  `remarks` TEXT,
  `by_hand` TINYINT(1) NOT NULL DEFAULT 0,
  `away_reason` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_attendance_user_id_att_date_key` (`user_id`, `att_date`),
  KEY `idx_staff_att_date` (`center_id`, `att_date`),
  CONSTRAINT `staff_attendance_status_check` CHECK ((status IN ('present', 'late', 'absent', 'leave', 'holiday')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_checkin_refusals` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `center_id` BIGINT,
  `att_date` DATE NOT NULL DEFAULT (CURDATE()),
  `at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `kind` TEXT NOT NULL,
  `latitude` DOUBLE,
  `longitude` DOUBLE,
  `accuracy_m` INT,
  `distance_m` INT,
  `radius_m` INT,
  `reason` TEXT,
  PRIMARY KEY (`id`),
  KEY `idx_refusals_recent` (`att_date`, `center_id`),
  CONSTRAINT `staff_checkin_refusals_kind_check` CHECK ((kind IN ('in', 'out')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_day_notes` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `role` VARCHAR(255) NOT NULL,
  `center_id` BIGINT,
  `session_id` BIGINT,
  `on_date` DATE NOT NULL DEFAULT (CURDATE()),
  `summary` TEXT,
  `where_worked` TEXT,
  `plan_next` TEXT,
  `support_needed` TEXT,
  `families_met` TEXT,
  `home_visits` TEXT,
  `concerns` TEXT,
  `follow_ups` TEXT,
  `what_checked` TEXT,
  `findings` TEXT,
  `urgent_issues` TEXT,
  `told_to_centre` TEXT,
  `sports_covered` TEXT,
  `activities` TEXT,
  `children_count` INT,
  `equipment_used` TEXT,
  `equipment_need` TEXT,
  `talent_spotted` TEXT,
  `injuries` TEXT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_day_notes_user_id_on_date_key` (`user_id`, `on_date`),
  KEY `idx_staff_day_notes` (`on_date`, `role`, `center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_leave_requests` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `center_id` BIGINT,
  `leave_type` TEXT NOT NULL,
  `starts_on` DATE NOT NULL,
  `ends_on` DATE NOT NULL,
  `half_day` TINYINT(1) NOT NULL DEFAULT 0,
  `reason` TEXT NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'pending',
  `decided_by` BIGINT,
  `decided_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `decision_note` TEXT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_leave_person` (`user_id`, `starts_on`),
  KEY `idx_leave_queue` (`status`, `starts_on`),
  KEY `idx_leave_span` (`starts_on`, `ends_on`),
  CONSTRAINT `leave_dates` CHECK ((ends_on >= starts_on)),
  CONSTRAINT `leave_decided` CHECK (((status IN ('pending', 'cancelled')) = (decided_by IS NULL))),
  CONSTRAINT `staff_leave_requests_leave_type_check` CHECK ((leave_type IN ('casual', 'sick', 'emergency', 'planned', 'unpaid'))),
  CONSTRAINT `staff_leave_requests_status_check` CHECK ((status IN ('pending', 'approved', 'rejected', 'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_punches` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `attendance_id` BIGINT NOT NULL,
  `user_id` BIGINT NOT NULL,
  `att_date` DATE NOT NULL,
  `check_in_at` TIMESTAMP(6) NOT NULL,
  `check_in_lat` DOUBLE,
  `check_in_lng` DOUBLE,
  `check_in_distance_m` INT,
  `check_in_accuracy_m` INT,
  `check_out_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `check_out_lat` DOUBLE,
  `check_out_lng` DOUBLE,
  `check_out_distance_m` INT,
  `check_out_accuracy_m` INT,
  `worked_minutes` INT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `by_hand` TINYINT(1) NOT NULL DEFAULT 0,
  `away_reason` TEXT,
  `_u_idx_staff_punch_open` TINYINT AS (CASE WHEN (check_out_at IS NULL) THEN 1 END) VIRTUAL INVISIBLE,
  PRIMARY KEY (`id`),
  KEY `idx_staff_punch_att` (`attendance_id`),
  KEY `idx_staff_punch_day` (`user_id`, `att_date`),
  UNIQUE KEY `idx_staff_punch_open` (`user_id`, `att_date`, `_u_idx_staff_punch_open`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_test_answers` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `test_id` BIGINT NOT NULL,
  `question_id` BIGINT NOT NULL,
  `position` SMALLINT NOT NULL,
  `chosen_index` SMALLINT,
  `is_correct` TINYINT(1),
  `answered_at` TIMESTAMP(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_test_answers_test_id_position_key` (`test_id`, `position`),
  UNIQUE KEY `staff_test_answers_test_id_question_id_key` (`test_id`, `question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_test_config` (
  `for_role` VARCHAR(255) NOT NULL,
  `duration_minutes` INT NOT NULL DEFAULT 10,
  `question_count` INT NOT NULL DEFAULT 10,
  `tests_per_month` INT NOT NULL DEFAULT 4,
  `avoid_last_tests` INT NOT NULL DEFAULT 2,
  `is_open` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_by` BIGINT,
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`for_role`),
  CONSTRAINT `staff_test_config_avoid_last_tests_check` CHECK (((avoid_last_tests >= 0) AND (avoid_last_tests <= 10))),
  CONSTRAINT `staff_test_config_duration_minutes_check` CHECK (((duration_minutes >= 1) AND (duration_minutes <= 180))),
  CONSTRAINT `staff_test_config_question_count_check` CHECK (((question_count >= 1) AND (question_count <= 50))),
  CONSTRAINT `staff_test_config_tests_per_month_check` CHECK (((tests_per_month >= 1) AND (tests_per_month <= 12)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_test_questions` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `for_role` VARCHAR(255) NOT NULL,
  `topic` TEXT,
  `question_en` TEXT NOT NULL,
  `question_hi` VARCHAR(255) NOT NULL,
  `options_en` JSON NOT NULL,
  `options_hi` JSON NOT NULL,
  `correct_index` SMALLINT NOT NULL,
  `note_en` TEXT,
  `note_hi` TEXT,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_staff_q_role` (`for_role`, `is_active`),
  UNIQUE KEY `uq_staff_q_text` (`for_role`, `question_hi`),
  CONSTRAINT `staff_q_options` CHECK ((((JSON_LENGTH(options_en) >= 2) AND (JSON_LENGTH(options_en) <= 6)) AND (JSON_LENGTH(options_hi) = JSON_LENGTH(options_en)) AND (correct_index >= 0) AND (correct_index < JSON_LENGTH(options_en))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_tests` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `for_role` VARCHAR(255) NOT NULL,
  `center_id` BIGINT,
  `cycle_month` DATE NOT NULL,
  `slot` SMALLINT NOT NULL,
  `duration_minutes` INT NOT NULL,
  `started_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `expires_at` TIMESTAMP(6) NOT NULL,
  `submitted_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `status` TEXT NOT NULL DEFAULT 'in_progress',
  `score` INT,
  `total` INT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_tests_user_id_cycle_month_slot_key` (`user_id`, `cycle_month`, `slot`),
  KEY `idx_staff_tests_recent` (`for_role`, `started_at`),
  KEY `idx_staff_tests_user` (`user_id`, `cycle_month`, `slot`),
  CONSTRAINT `staff_tests_slot_check` CHECK (((slot >= 1) AND (slot <= 12))),
  CONSTRAINT `staff_tests_status_check` CHECK ((status IN ('in_progress', 'submitted', 'expired')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_attendance` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `student_id` BIGINT NOT NULL,
  `enrollment_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `att_date` DATE NOT NULL,
  `status` TEXT NOT NULL,
  `remarks` TEXT,
  `marked_by` BIGINT,
  `marked_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `reason` VARCHAR(255),
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_attendance_student_id_att_date_key` (`student_id`, `att_date`),
  KEY `idx_satt_class_date` (`session_id`, `class_level_id`, `att_date`),
  KEY `idx_satt_date` (`att_date`),
  KEY `idx_satt_reason` (`center_id`, `reason`),
  CONSTRAINT `student_attendance_reason_check` CHECK (((reason IS NULL) OR ((status = 'absent') AND (reason IN ('Sick', 'Didn''t wake up', 'Distance issue', 'Parents allowed it', 'Siblings responsibility', 'Visiting Hometown', 'Need Followup', 'Parents not aware', 'Drop'))) OR ((status = 'leave') AND (reason IN ('Approved leave', 'Festival', 'Marriage'))))),
  CONSTRAINT `student_attendance_status_check` CHECK ((status IN ('present', 'absent', 'late', 'half_day', 'leave', 'holiday')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_reactivations` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `student_id` BIGINT NOT NULL,
  `session_id` BIGINT,
  `from_status` TEXT NOT NULL,
  `from_center_id` BIGINT,
  `to_center_id` BIGINT NOT NULL,
  `from_class_id` BIGINT,
  `to_class_id` BIGINT NOT NULL,
  `reactivated_on` DATE NOT NULL DEFAULT (CURDATE()),
  `left_reason` TEXT,
  `note` TEXT,
  `reactivated_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_reactivations_day` (`reactivated_on`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_siblings` (
  `student_a` BIGINT NOT NULL,
  `student_b` BIGINT NOT NULL,
  `confirmed_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`student_a`, `student_b`),
  KEY `idx_siblings_b` (`student_b`),
  CONSTRAINT `siblings_ordered` CHECK ((student_a < student_b))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_supply_issues` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `item_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `session_id` BIGINT,
  `quantity` INT NOT NULL,
  `issued_on` DATE NOT NULL DEFAULT (CURDATE()),
  `remarks` TEXT,
  `issued_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_issues_center` (`center_id`, `issued_on`),
  KEY `idx_issues_student` (`student_id`),
  CONSTRAINT `student_supply_issues_quantity_check` CHECK ((quantity > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_transfers` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `student_id` BIGINT NOT NULL,
  `session_id` BIGINT,
  `from_center_id` BIGINT NOT NULL,
  `to_center_id` BIGINT NOT NULL,
  `from_class_id` BIGINT,
  `to_class_id` BIGINT,
  `transferred_on` DATE NOT NULL DEFAULT (CURDATE()),
  `reason` TEXT,
  `moved_history` TINYINT(1) NOT NULL DEFAULT 1,
  `moved_attendance` INT NOT NULL DEFAULT 0,
  `moved_ptm` INT NOT NULL DEFAULT 0,
  `moved_referrals` INT NOT NULL DEFAULT 0,
  `left_sports` INT NOT NULL DEFAULT 0,
  `transferred_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_transfers_day` (`transferred_on`),
  KEY `idx_transfers_student` (`student_id`, `transferred_on`),
  CONSTRAINT `transfer_somewhere` CHECK ((from_center_id <> to_center_id))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `students` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `enrollment_no` VARCHAR(255) NOT NULL,
  `center_id` BIGINT NOT NULL,
  `first_name` TEXT NOT NULL,
  `last_name` TEXT,
  `gender` TEXT,
  `dob` DATE,
  `father_name` TEXT,
  `mother_name` TEXT,
  `guardian_name` TEXT,
  `primary_phone` TEXT,
  `alt_phone` TEXT,
  `email` TEXT,
  `address` TEXT,
  `photo_url` TEXT,
  `admission_date` DATE NOT NULL DEFAULT (CURDATE()),
  `status` VARCHAR(255) NOT NULL DEFAULT 'active',
  `notes` TEXT,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `admission_no` VARCHAR(255),
  `registration_no` TEXT,
  `photo_media_id` BIGINT,
  `place_of_birth` TEXT,
  `nationality` TEXT,
  `religion` TEXT,
  `caste` TEXT,
  `category` TEXT,
  `blood_group` TEXT,
  `has_disability` TINYINT(1) NOT NULL DEFAULT 0,
  `disability_details` TEXT,
  `whatsapp_number` TEXT,
  `house_block` TEXT,
  `pincode` TEXT,
  `city` TEXT,
  `state` TEXT,
  `country` TEXT DEFAULT 'India',
  `mother_qualification` TEXT,
  `mother_occupation` TEXT,
  `mother_income` DECIMAL(12,2),
  `mother_email` TEXT,
  `mother_mobile` TEXT,
  `mother_photo_media_id` BIGINT,
  `father_qualification` TEXT,
  `father_occupation` TEXT,
  `father_income` DECIMAL(12,2),
  `father_email` TEXT,
  `father_mobile` TEXT,
  `father_photo_media_id` BIGINT,
  `guardian_qualification` TEXT,
  `guardian_occupation` TEXT,
  `guardian_income` DECIMAL(12,2),
  `guardian_email` TEXT,
  `guardian_mobile` TEXT,
  `guardian_photo_media_id` BIGINT,
  `udise` TINYINT(1),
  `rte_application_no` TEXT,
  `apaar_id` TEXT,
  `aadhaar_number` TEXT,
  `mother_occupation_other` TEXT,
  `father_occupation_other` TEXT,
  `guardian_occupation_other` TEXT,
  `legacy_student_id` VARCHAR(255),
  `medium` TEXT,
  `is_rte` TINYINT(1) NOT NULL DEFAULT 0,
  `is_bpl` TINYINT(1) NOT NULL DEFAULT 0,
  `dob_application_no` TEXT,
  `samagra_id` TEXT,
  `reference` TEXT,
  `tc_date` DATE,
  `dropout_reason` TEXT,
  `dropout_date` DATE,
  `mother_aadhaar_number` TEXT,
  `father_aadhaar_number` TEXT,
  `guardian_aadhaar_number` TEXT,
  `mother_residential_address` TEXT,
  `father_residential_address` TEXT,
  `guardian_residential_address` TEXT,
  `mother_official_address` TEXT,
  `father_official_address` TEXT,
  `guardian_official_address` TEXT,
  `dropout_remarks` TEXT,
  `dropout_marked_by` BIGINT,
  `dropout_marked_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `aadhaar_media_id` BIGINT,
  `father_aadhaar_media_id` BIGINT,
  `mother_aadhaar_media_id` BIGINT,
  `guardian_aadhaar_media_id` BIGINT,
  `left_on` DATE,
  `left_reason` TEXT,
  `status_changed_by` BIGINT,
  `status_changed_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `transport_mode` TEXT,
  `_u_uniq_students_center_admission_no` TINYINT AS (CASE WHEN (admission_no IS NOT NULL) THEN 1 END) VIRTUAL INVISIBLE,
  PRIMARY KEY (`id`),
  UNIQUE KEY `students_enrollment_no_key` (`enrollment_no`),
  KEY `idx_students_center` (`center_id`),
  KEY `idx_students_dropped` (`center_id`, `dropout_date`),
  KEY `idx_students_legacy_id` (`legacy_student_id`),
  KEY `idx_students_status` (`status`),
  KEY `idx_students_suspended` (`center_id`, `left_on`),
  UNIQUE KEY `uniq_students_center_admission_no` (`center_id`, `admission_no`, `_u_uniq_students_center_admission_no`),
  CONSTRAINT `students_gender_check` CHECK ((gender IN ('male', 'female', 'other'))),
  CONSTRAINT `students_status_check` CHECK ((status IN ('active', 'inactive', 'graduated', 'transferred', 'dropped', 'suspended'))),
  CONSTRAINT `students_transport_mode_check` CHECK ((transport_mode IN ('rickshaw', 'cycle', 'walk')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `supply_items` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `category` TEXT NOT NULL DEFAULT 'stationery',
  `unit` TEXT NOT NULL DEFAULT 'piece',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `supply_items_name_key` (`name`),
  CONSTRAINT `supply_items_category_check` CHECK ((category IN ('stationery', 'books', 'uniform', 'hygiene', 'equipment', 'other')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `supply_requests` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `center_id` BIGINT NOT NULL,
  `item_id` BIGINT NOT NULL,
  `quantity` INT NOT NULL,
  `reason` TEXT,
  `requested_by` BIGINT NOT NULL,
  `requested_on` DATE NOT NULL DEFAULT (CURDATE()),
  `status` TEXT NOT NULL DEFAULT 'pending',
  `notes` TEXT,
  `handled_by` BIGINT,
  `handled_on` DATE,
  `receipt_id` BIGINT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_completions` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `topic_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `marked_by` BIGINT,
  `marked_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `note` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE KEY `syllabus_completions_topic_id_center_id_session_id_key` (`topic_id`, `center_id`, `session_id`),
  KEY `idx_syllabus_completions_center` (`center_id`, `session_id`, `topic_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_item_ticks` (
  `item_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `done_on` DATE NOT NULL DEFAULT (CURDATE()),
  `marked_by` BIGINT,
  PRIMARY KEY (`item_id`, `center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_items` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `unit_id` BIGINT NOT NULL,
  `position` INT NOT NULL DEFAULT 0,
  `text` TEXT NOT NULL,
  `week_no` INT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_syllabus_items` (`unit_id`, `position`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_progress` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `unit_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'not_started',
  `completed_on` DATE,
  `remarks` TEXT,
  `marked_by` BIGINT,
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `syllabus_progress_unit_id_center_id_key` (`unit_id`, `center_id`),
  KEY `idx_syllabus_progress` (`center_id`, `status`),
  CONSTRAINT `syllabus_progress_status_check` CHECK ((status IN ('not_started', 'in_progress', 'completed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_topics` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `subject` VARCHAR(255) NOT NULL,
  `class_level` VARCHAR(255) NOT NULL,
  `month_no` SMALLINT NOT NULL,
  `week_no` SMALLINT,
  `title` TEXT NOT NULL,
  `description` TEXT,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_syllabus_topics_class` (`class_level`, `subject`, `month_no`, `week_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_units` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT NOT NULL,
  `subject` VARCHAR(255) NOT NULL,
  `month_no` INT NOT NULL,
  `heading` TEXT,
  `outcome` TEXT,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `term_no` SMALLINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `syllabus_units_term_month_unique` (`session_id`, `class_level_id`, `subject`, `term_no`, `month_no`),
  KEY `idx_syllabus_scope` (`session_id`, `class_level_id`, `subject`, `term_no`, `month_no`),
  CONSTRAINT `syllabus_units_month_no_check` CHECK (((month_no >= 1) AND (month_no <= 3))),
  CONSTRAINT `syllabus_units_term_no_check` CHECK (((term_no >= 1) AND (term_no <= 3)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `syllabus_week_progress` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `unit_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `week_no` INT NOT NULL,
  `remarks` TEXT,
  `marked_by` BIGINT,
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `syllabus_week_progress_unit_id_center_id_week_no_key` (`unit_id`, `center_id`, `week_no`),
  KEY `idx_swp_unit` (`unit_id`, `center_id`),
  CONSTRAINT `syllabus_week_progress_week_no_check` CHECK (((week_no >= 1) AND (week_no <= 4)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teacher_classes` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `is_class_teacher` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `teacher_classes_user_id_session_id_class_level_id_key` (`user_id`, `session_id`, `class_level_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teacher_coverage` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `backup_id` BIGINT NOT NULL,
  `covering_id` BIGINT NOT NULL,
  `center_id` BIGINT NOT NULL,
  `session_id` BIGINT,
  `starts_on` DATE NOT NULL DEFAULT (CURDATE()),
  `ends_on` DATE,
  `reason` TEXT,
  `assigned_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_coverage_backup` (`backup_id`, `starts_on`, `ends_on`),
  KEY `idx_coverage_covering` (`covering_id`),
  CONSTRAINT `coverage_dates` CHECK (((ends_on IS NULL) OR (ends_on >= starts_on))),
  CONSTRAINT `coverage_not_self` CHECK ((backup_id <> covering_id))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teacher_day_notes` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `center_id` BIGINT,
  `class_level_id` BIGINT,
  `session_id` BIGINT,
  `on_date` DATE NOT NULL DEFAULT (CURDATE()),
  `subject` TEXT,
  `chapter` TEXT,
  `chapter_detail` TEXT,
  `homework` TEXT,
  `homework_detail` TEXT,
  `equipment` TEXT,
  `equipment_result` TEXT,
  `other_work` TEXT,
  `support_needed` TEXT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `extra_activity` TEXT,
  `extra_detail` TEXT,
  `_cl0` BIGINT AS (COALESCE(`class_level_id`, 0)) VIRTUAL INVISIBLE,
  PRIMARY KEY (`id`),
  KEY `idx_teacher_day_notes` (`on_date`, `center_id`),
  UNIQUE KEY `uq_teacher_day_note` (`user_id`, `on_date`, `_cl0`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teaching_plan_topics` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `plan_id` BIGINT NOT NULL,
  `sequence` INT NOT NULL DEFAULT 1,
  `topic` TEXT NOT NULL,
  `objective` TEXT,
  `planned_date` DATE,
  `status` VARCHAR(255) NOT NULL DEFAULT 'planned',
  `taught_on` DATE,
  `taught_by` BIGINT,
  `remarks` TEXT,
  `resources_used` TEXT,
  `issues_faced` TEXT,
  `completed_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_topics_plan` (`plan_id`, `sequence`),
  KEY `idx_topics_status` (`status`),
  CONSTRAINT `teaching_plan_topics_status_check` CHECK ((status IN ('planned', 'in_progress', 'completed', 'skipped')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `teaching_plans` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `title` TEXT NOT NULL,
  `subject` TEXT,
  `center_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT NOT NULL,
  `teacher_id` BIGINT NOT NULL,
  `description` TEXT,
  `starts_on` DATE,
  `ends_on` DATE,
  `status` VARCHAR(255) NOT NULL DEFAULT 'draft',
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `submitted_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `submitted_by` BIGINT,
  PRIMARY KEY (`id`),
  KEY `idx_plans_class` (`session_id`, `class_level_id`, `center_id`),
  KEY `idx_plans_status` (`status`, `starts_on`),
  KEY `idx_plans_teacher` (`teacher_id`, `session_id`),
  CONSTRAINT `teaching_plans_status_check` CHECK ((status IN ('draft', 'submitted', 'active', 'completed', 'archived')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `timetable_slots` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `center_id` BIGINT NOT NULL,
  `session_id` BIGINT NOT NULL,
  `class_level_id` BIGINT NOT NULL,
  `day_of_week` SMALLINT NOT NULL,
  `period_no` SMALLINT NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `subject` TEXT NOT NULL,
  `teacher_id` BIGINT,
  `room` TEXT,
  `created_by` BIGINT,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `_u_timetable_teacher_busy` TINYINT AS (CASE WHEN (teacher_id IS NOT NULL) THEN 1 END) VIRTUAL INVISIBLE,
  PRIMARY KEY (`id`),
  UNIQUE KEY `timetable_slots_center_id_session_id_class_level_id_day_of__key` (`center_id`, `session_id`, `class_level_id`, `day_of_week`, `period_no`),
  KEY `idx_tt_class` (`center_id`, `session_id`, `class_level_id`, `day_of_week`, `period_no`),
  KEY `idx_tt_teacher` (`teacher_id`, `session_id`, `day_of_week`, `period_no`),
  UNIQUE KEY `timetable_teacher_busy` (`center_id`, `session_id`, `teacher_id`, `day_of_week`, `period_no`, `_u_timetable_teacher_busy`),
  CONSTRAINT `timetable_slots_day_of_week_check` CHECK (((day_of_week >= 1) AND (day_of_week <= 7))),
  CONSTRAINT `timetable_slots_period_no_check` CHECK (((period_no >= 1) AND (period_no <= 12))),
  CONSTRAINT `timetable_times` CHECK ((end_time > start_time))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user_menu_overrides` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT NOT NULL,
  `menu_key` VARCHAR(255) NOT NULL,
  `hidden` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_menu_overrides_user_id_menu_key_key` (`user_id`, `menu_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `users` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `name` TEXT NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `phone` TEXT,
  `password_hash` TEXT NOT NULL,
  `role` VARCHAR(255) NOT NULL,
  `center_id` BIGINT,
  `designation` TEXT,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login_at` TIMESTAMP(6) NULL DEFAULT NULL,
  `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `is_test` TINYINT(1) NOT NULL DEFAULT 0,
  `subject` TEXT,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_key` (`email`),
  KEY `idx_users_center` (`center_id`),
  KEY `idx_users_real` (`role`),
  CONSTRAINT `users_role_check` CHECK ((role IN ('super_admin', 'admin', 'mentor', 'center_manager', 'teacher', 'backup_teacher', 'auditor', 'sports_teacher', 'rider')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
